const result = $input.first().json;
const regime = result.regime || 'UNKNOWN';
const prev = result.previous_regime || null;
const snap = result.snapshot || {};
const regimeChanged = prev && prev !== regime;
const rr = snap.real_rate != null ? snap.real_rate.toFixed(2) : 'N/A';
const dxy = snap.dxy != null ? snap.dxy.toFixed(1) : 'N/A';
const vix = snap.vix != null ? snap.vix.toFixed(1) : 'N/A';
const gvzVix = snap.gvz_vix_ratio != null ? snap.gvz_vix_ratio.toFixed(2) : 'N/A';
const news = snap.news_sentiment != null ? snap.news_sentiment.toFixed(3) : 'N/A';
const regimeEmoji = regime === 'BULLISH' ? '🟢' : regime === 'BEARISH' ? '🔴' : '🟡';
const changeNote = regimeChanged ? ` (was ${prev})` : '';
const msg = [
  regimeEmoji + ' **Regime: ' + regime + changeNote + '**',
  'Real Rate: ' + rr + '% | DXY: ' + dxy + ' | VIX: ' + vix,
  'GVZ/VIX: ' + gvzVix + ' | News: ' + news,
].join('\n');
return [{ json: { regime, prev, regimeChanged, message: msg } }];
